from fractions import Fraction as F
rows=[('A',13,(1,0,0,0)),('A',3,(0,0,0,1)),('B',9,(1,0,1,0)),('B',5,(0,0,1,1)),('C',5,(1,1,1,0)),('C',8,(0,0,1,0)),('D',6,(1,0,0,0)),('D',5,(0,0,1,1))]
names='TUVW'
cost=dict(zip(names,map(F,['1.8','1.5','1.2','0.8'])))
loss=[[0,11,6,16],[22,0,20,8],[16,23,0,7],[18,11,20,0]]
def stop(ids):
    w=sum(rows[i][1] for i in ids)
    return min((F(sum(rows[i][1]*loss[a]['ABCD'.index(rows[i][0])] for i in ids),w),'ABCD'[a]) for a in range(4))
def solve(ids,avail,budget):
    best,act=stop(ids)
    if budget:
        for t in avail:
            val=cost[t]
            for b in [0,1]:
                child=tuple(i for i in ids if rows[i][2][names.index(t)]==b)
                if child:
                    val+=F(sum(rows[i][1] for i in child),sum(rows[i][1] for i in ids))*solve(child,avail.replace(t,''),budget-1)[0]
            if val<best: best,act=val,t
    return best,act
ids=tuple(range(8))
first_losses={'STOP':float(stop(ids)[0])}
for t in names:
    val=cost[t]
    for b in [0,1]:
        child=tuple(i for i in ids if rows[i][2][names.index(t)]==b)
        if child: val+=F(sum(rows[i][1] for i in child),54)*solve(child,names.replace(t,''),1)[0]
    first_losses[t]=float(val)
best,first=solve(ids,names,2)
nxt={}
if first in names:
    for b in [0,1]:
        child=tuple(i for i in ids if rows[i][2][names.index(first)]==b)
        nxt[str(b)]=solve(child,names.replace(first,''),1)[1] if child else 'IMPOSSIBLE'
print(sum(r[1] for r in rows))
print({'first':first,'first_losses':first_losses,'next':nxt})

