from fractions import Fraction as F
# W=1 leaves A drift (3), B drift (5), D drift (5).
rows=[('A',3,{'T':0,'U':0,'V':0}),('B',5,{'T':0,'U':0,'V':1}),('D',5,{'T':0,'U':0,'V':1})]
L={'A':[0,11,6,16],'B':[22,0,20,8],'C':[16,23,0,7],'D':[18,11,20,0]}
def repair(rs):
    total=sum(r[1] for r in rs)
    return min((F(sum(w*ls['ABCD'.index(m)] for m,w,_ in rs),total),a) for a,ls in L.items())
out={a:float(F(sum(w*ls['ABCD'.index(m)] for m,w,_ in rows),13)) for a,ls in L.items()}
for t,c in [('T',F('1.8')),('U',F('1.5')),('V',F('7.2'))]:
    val=c
    for b in [0,1]:
        rs=[r for r in rows if r[2][t]==b]
        if rs: val+=F(sum(r[1] for r in rs),13)*repair(rs)[0]
    out[t]=float(val)
print({'posterior':{'A':3/13,'B':5/13,'C':0,'D':5/13},'remaining_losses':out,'action':min(out,key=out.get),'repair_after':{}})

